1	package masker
2	
3	import (
4		"fmt"
5		"reflect"
6		"strings"
7		"sync"
8	)
9	
10	const tagName = "mask"
11	
12	// MaskerType 是遮罩型別的字串別名，對應 struct tag `mask:"..."` 的值。
13	type MaskerType string
14	
15	// MaskerType 常數。v3 採用精簡命名（保留 Type prefix 以避免與其他識別字衝突）。
16	const (
17		TypeNone      MaskerType = "none"
18		TypePassword  MaskerType = "password"
19		TypeName      MaskerType = "name"
20		TypeAddress   MaskerType = "addr"
21		TypeEmail     MaskerType = "email"
22		TypeMobile    MaskerType = "mobile"
23		TypeTel       MaskerType = "tel"
24		TypeID        MaskerType = "id"
25		TypeCredit    MaskerType = "credit"
26		TypeURL       MaskerType = "url"
27		TypeAbuse     MaskerType = "abuse"
28		TypeStruct    MaskerType = "struct"
29		TypeAll       MaskerType = "all"
30		TypeMapStruct MaskerType = "mapstruct"
31	)
32	
33	// Masker 是遮罩單一字串的介面。
34	// 遮罩字元已於建構時注入各實作，呼叫者只需提供待遮罩的值。
35	// 實作自訂 masker 時，實作此介面並透過 MaskerMarshaler.Register 註冊即可。
36	type Masker interface {
37		Mask(value string) string
38	}
39	
40	// Option 是 MaskerMarshaler 的建構選項，遵循 functional options 模式。
41	type Option func(*MaskerMarshaler)
42	
43	// WithMaskChar 設定此 marshaler 使用的遮罩字元，預設為 '*'。
44	// 設定後僅影響由此 marshaler 建立的 masker 實例，不會污染 DefaultMaskerMarshaler。
45	// 注意：URLMasker（密碼段固定輸出 xxxxx）與 NoneMasker（原樣回傳）不受此設定影響。
46	func WithMaskChar(c rune) Option {
47		return func(m *MaskerMarshaler) {
48			m.maskChar = string(c)
49		}
50	}
51	
52	// MaskerMarshaler 管理一組 masker 並提供 Marshal 與 Struct 等遮罩操作。
53	// 所有 exported 方法皆可安全並行使用。
54	// 直接存取 Maskers 欄位並非並行安全，請改用 Register/Get。
55	type MaskerMarshaler struct {
56		mu       sync.RWMutex
57		Maskers  map[MaskerType]Masker
58		maskChar string
59	}
60	
61	// Marshal 依 masker 型別回傳遮罩後的值，找不到型別時回傳 error。
62	// 同時支援動態 tag first-N / last-N，這類 tag 不需事先註冊。
63	// Example:
64	//
65	//	m := masker.NewMaskerMarshaler()
66	//	s, _ := m.Marshal(masker.TypeMobile, "0987654321") // 0987***321
67	func (m *MaskerMarshaler) Marshal(t MaskerType, value string) (string, error) {
68		m.mu.RLock()
69		defer m.mu.RUnlock()
70		if result, matched, err := parseGenericMask(m.maskChar, string(t), value); matched {
71			return result, err
72		}
73		masker, ok := m.Maskers[t]
74		if !ok {
75			return "", fmt.Errorf("masker %v not found", t)
76		}
77		return masker.Mask(value), nil
78	}
79	
80	// MustMarshal 與 Marshal 相同，但找不到 masker 型別時直接 panic。
81	// 適用於呼叫者確信型別存在、不想處理 error 的場景。
82	// Example:
83	//
84	//	m := masker.NewMaskerMarshaler()
85	//	s := m.MustMarshal(masker.TypeMobile, "0987654321") // 0987***321
86	func (m *MaskerMarshaler) MustMarshal(t MaskerType, value string) string {
87		result, err := m.Marshal(t, value)
88		if err != nil {
89			panic(err)
90		}
91		return result
92	}
93	
94	// Register 以 masker 型別新增或覆寫一個 masker。
95	func (m *MaskerMarshaler) Register(t MaskerType, masker Masker) {
96		m.mu.Lock()
97		defer m.mu.Unlock()
98		m.Maskers[t] = masker
99	}
100	
101	// Unregister 移除指定型別的 masker。
102	func (m *MaskerMarshaler) Unregister(t MaskerType) {
103		m.mu.Lock()
104		defer m.mu.Unlock()
105		delete(m.Maskers, t)
106	}
107	
108	// Get 回傳指定型別的 masker，找不到時回傳 error。
109	func (m *MaskerMarshaler) Get(t MaskerType) (Masker, error) {
110		m.mu.RLock()
111		defer m.mu.RUnlock()
112		masker, ok := m.Maskers[t]
113		if !ok {
114			return nil, fmt.Errorf("masker %v not found", t)
115		}
116		return masker, nil
117	}
118	
119	// List 回傳目前已註冊的所有 masker 型別。
120	func (m *MaskerMarshaler) List() []MaskerType {
121		m.mu.RLock()
122		defer m.mu.RUnlock()
123		var list []MaskerType
124		for t := range m.Maskers {
125			list = append(list, t)
126		}
127		return list
128	}
129	
130	// Struct 接收 struct 或 struct 指標，依欄位上的 `mask` tag 遮罩後回傳同型別的指標。
131	// 原輸入不會被修改。
132	//
133	// Limitation:
134	//   - 不特別處理循環物件圖；自我參照結構在 `mask:"struct"` 或 `mask:"mapstruct"` 下可能無限遞迴。
135	//
136	// Example:
137	//
138	//	type Foo struct {
139	//		Name  string `mask:"name"`
140	//		Email string `mask:"email"`
141	//	}
142	//	m := masker.NewMaskerMarshaler()
143	//	out, _ := m.Struct(&Foo{Name: "John Doe", Email: "john@gmail.com"})
144	func (m *MaskerMarshaler) Struct(s interface{}) (interface{}, error) {
145		if s == nil {
146			return nil, fmt.Errorf("input is nil")
147		}
148	
149		var selem, tptr reflect.Value
150	
151		st := reflect.TypeOf(s)
152		sv := reflect.ValueOf(s)
153	
154		actualKind := st.Kind()
155		if actualKind == reflect.Ptr {
156			if sv.IsNil() {
157				return nil, fmt.Errorf("input is nil pointer")
158			}
159			actualKind = st.Elem().Kind()
160		}
161		if actualKind != reflect.Struct {
162			return nil, fmt.Errorf("input must be a struct or pointer to struct, got %v", actualKind)
163		}
164	
165		if st.Kind() == reflect.Ptr {
166			tptr = reflect.New(st.Elem())
167			selem = sv.Elem()
168		} else {
169			tptr = reflect.New(st)
170			selem = sv
171		}
172	
173		for i := 0; i < selem.NumField(); i++ {
174			if !selem.Type().Field(i).IsExported() {
175				continue
176			}
177			mtag := selem.Type().Field(i).Tag.Get(tagName)
178			if len(mtag) == 0 {
179				tptr.Elem().Field(i).Set(selem.Field(i))
180				continue
181			}
182	
183			switch selem.Field(i).Type().Kind() {
184			default:
185				tptr.Elem().Field(i).Set(selem.Field(i))
186			case reflect.String:
187				v, err := m.Marshal(MaskerType(mtag), selem.Field(i).String())
188				if err != nil {
189					return nil, err
190				}
191				tptr.Elem().Field(i).SetString(v)
192			case reflect.Struct:
193				if MaskerType(mtag) == TypeStruct {
194					_t, err := m.Struct(selem.Field(i).Interface())
195					if err != nil {
196						return nil, err
197					}
198					tptr.Elem().Field(i).Set(reflect.ValueOf(_t).Elem())
199				} else {
200					tptr.Elem().Field(i).Set(selem.Field(i))
201				}
202			case reflect.Ptr:
203				if selem.Field(i).IsNil() {
204					continue
205				}
206				if MaskerType(mtag) == TypeStruct {
207					_t, err := m.Struct(selem.Field(i).Interface())
208					if err != nil {
209						return nil, err
210					}
211					tptr.Elem().Field(i).Set(reflect.ValueOf(_t))
212				} else {
213					tptr.Elem().Field(i).Set(selem.Field(i))
214				}
215			case reflect.Map:
216				if selem.Field(i).IsNil() {
217					continue
218				}
219				if MaskerType(mtag) != TypeMapStruct {
220					tptr.Elem().Field(i).Set(selem.Field(i))
221					continue
222				}
223	
224				maskedMap := reflect.MakeMapWithSize(selem.Field(i).Type(), selem.Field(i).Len())
225				iter := selem.Field(i).MapRange()
226				for iter.Next() {
227					v := iter.Value()
228					maskedValue, err := m.maskMapStructValue(v)
229					if err != nil {
230						return nil, err
231					}
232	
233					maskedMap.SetMapIndex(iter.Key(), maskedValue)
234				}
235				tptr.Elem().Field(i).Set(maskedMap)
236				continue
237	
238			case reflect.Slice:
239				if selem.Field(i).IsNil() {
240					continue
241				}
242				switch {
243				case selem.Field(i).Type().Elem().Kind() == reflect.String:
244					orgval := selem.Field(i).Interface().([]string)
245					newval := make([]string, len(orgval))
246					for i, val := range selem.Field(i).Interface().([]string) {
247						v, err := m.Marshal(MaskerType(mtag), val)
248						if err != nil {
249							return nil, err
250						}
251						newval[i] = v
252					}
253					tptr.Elem().Field(i).Set(reflect.ValueOf(newval))
254				case selem.Field(i).Type().Elem().Kind() == reflect.Struct && MaskerType(mtag) == TypeStruct:
255					newval := reflect.MakeSlice(selem.Field(i).Type(), 0, selem.Field(i).Len())
256					for j, l := 0, selem.Field(i).Len(); j < l; j++ {
257						_n, err := m.Struct(selem.Field(i).Index(j).Interface())
258						if err != nil {
259							return nil, err
260						}
261						newval = reflect.Append(newval, reflect.ValueOf(_n).Elem())
262					}
263					tptr.Elem().Field(i).Set(newval)
264				case selem.Field(i).Type().Elem().Kind() == reflect.Ptr && MaskerType(mtag) == TypeStruct:
265					newval := reflect.MakeSlice(selem.Field(i).Type(), 0, selem.Field(i).Len())
266					for j, l := 0, selem.Field(i).Len(); j < l; j++ {
267						if selem.Field(i).Index(j).IsNil() {
268							newval = reflect.Append(newval, selem.Field(i).Index(j))
269							continue
270						}
271						_n, err := m.Struct(selem.Field(i).Index(j).Interface())
272						if err != nil {
273							return nil, err
274						}
275						newval = reflect.Append(newval, reflect.ValueOf(_n))
276					}
277					tptr.Elem().Field(i).Set(newval)
278				case selem.Field(i).Type().Elem().Kind() == reflect.Interface && MaskerType(mtag) == TypeStruct:
279					newval := reflect.MakeSlice(selem.Field(i).Type(), 0, selem.Field(i).Len())
280					for j, l := 0, selem.Field(i).Len(); j < l; j++ {
281						_n, err := m.Struct(selem.Field(i).Index(j).Interface())
282						if err != nil {
283							return nil, err
284						}
285						if reflect.TypeOf(selem.Field(i).Index(j).Interface()).Kind() != reflect.Ptr {
286							newval = reflect.Append(newval, reflect.ValueOf(_n).Elem())
287						} else {
288							newval = reflect.Append(newval, reflect.ValueOf(_n))
289						}
290					}
291					tptr.Elem().Field(i).Set(newval)
292				default:
293					tptr.Elem().Field(i).Set(selem.Field(i))
294				}
295			case reflect.Interface:
296				if selem.Field(i).IsNil() {
297					continue
298				}
299				if MaskerType(mtag) != TypeStruct {
300					continue
301				}
302				_t, err := m.Struct(selem.Field(i).Interface())
303				if err != nil {
304					return nil, err
305				}
306				if reflect.TypeOf(selem.Field(i).Interface()).Kind() != reflect.Ptr {
307					tptr.Elem().Field(i).Set(reflect.ValueOf(_t).Elem())
308				} else {
309					tptr.Elem().Field(i).Set(reflect.ValueOf(_t))
310				}
311			}
312		}
313	
314		return tptr.Interface(), nil
315	}
316	
317	// maskMapStructValue 遞迴遮罩 mapstruct 的值，支援 struct、ptr、slice、map 形狀。
318	// 不支援的純量／容器葉節點原樣回傳以保留原始資料。
319	// 注意：不處理循環物件圖，可能造成 stack overflow。
