345			}
346			maskedElem, err := m.maskMapStructValue(v.Elem())
347			if err != nil {
348				return reflect.Value{}, err
349			}
350			maskedPtr := reflect.New(v.Elem().Type())
351			maskedPtr.Elem().Set(maskedElem)
352			return maskedPtr, nil
353		case reflect.Slice:
354			if v.IsNil() {
355				return v, nil
356			}
357			maskedSlice := reflect.MakeSlice(v.Type(), 0, v.Len())
358			for i := 0; i < v.Len(); i++ {
359				maskedElem, err := m.maskMapStructValue(v.Index(i))
360				if err != nil {
361					return reflect.Value{}, err
362				}
363				maskedSlice = reflect.Append(maskedSlice, maskedElem)
364			}
365			return maskedSlice, nil
366		default:
367			return v, nil
368		}
369	}
370	
371	// NewMaskerMarshaler 建立一個新的 MaskerMarshaler，並註冊全部預設 masker。
372	// 預設遮罩字元為 '*'，可透過 WithMaskChar 選項變更。
