391			TypeURL:      &URLMasker{},
392			TypeAbuse:    NewAbuseMasker(c),
393			TypeAll:      &AllMasker{mask: c},
394		}
395		return m
396	}
397	
398	// DefaultMaskerMarshaler 是預設的 MaskerMarshaler，遮罩字元為 '*'，供 package-level 便利函式使用。
399	var DefaultMaskerMarshaler = NewMaskerMarshaler()
