===== v3/mobile.go =====
package masker

// MobileMasker 是手機號碼的 masker。
type MobileMasker struct {
	mask string
}

// Mask 遮罩手機號碼，從第 4 位起遮罩 3 碼。
// Example:
//
//	(&MobileMasker{mask: "*"}).Mask("0987654321") // returns "0987***321"
func (m *MobileMasker) Mask(value string) string {
	if len(value) == 0 {
		return ""
	}
	return overlay(value, strLoop(m.mask, 3), 4, 7)
}
===== v3/email.go =====
package masker

import "strings"

// EmailMasker 是 email 的 masker。
type EmailMasker struct {
	mask string
}

// Mask 遮罩 email，保留網域與前 3 個字元。
// Example:
//
//	(&EmailMasker{mask: "*"}).Mask("ggw.chang@gmail.com") // returns "ggw****@gmail.com"
func (m *EmailMasker) Mask(value string) string {
	l := len([]rune(value))
	if l == 0 {
		return ""
	}

	tmp := strings.Split(value, "@")
	if len(tmp) == 1 {
		return overlay(value, strLoop(m.mask, 4), 3, 7)
	}

	addr := tmp[0]
	domain := tmp[1]

	addr = overlay(addr, strLoop(m.mask, 4), 3, len(addr))

	return addr + "@" + domain
}
