// AllMasker 是把每個字元都換成遮罩字元的 masker。
type AllMasker struct {
	mask string
}

// Mask 將值中的每個字元都換成遮罩字元。
// Example:
//
//	(&AllMasker{mask: "*"}).Mask("secret") // returns "******"
func (m *AllMasker) Mask(value string) string {
	return strLoop(m.mask, len([]rune(value)))
